import React, { useState, useEffect } from 'react';
import axiosInstance from 'axios';

export default function TeacherQuiz({ userName, subject, qualifications }) {
  // 🟢 100% CLEAN: කෝඩ් එක ඇතුළේ කිසිම දත්තයක් හාඩ්කෝඩ් කර නැත. සියල්ල ඩේටාබේස් එකෙන් පැමිණේ.
  const [quizzes, setQuizzes] = useState([]);
  const [masterBank, setMasterBank] = useState([]);

  const [selectedQuizId, setSelectedQuizId] = useState('');
  const [quizTitle, setQuizTitle] = useState('');
  
  // Form States
  const [editingId, setEditingId] = useState(null);
  const [qText, setQText] = useState('');
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');
  const [correctOpt, setCorrectOpt] = useState('A');
  const [qMarks, setQMarks] = useState(2);

  const fullSubject = subject || 'Grade 8 - Mathematics';
  const subjectParts = fullSubject.split(' - ');
  const teachingGrade = subjectParts.length > 1 ? subjectParts[0] : 'Grade 8';
  let teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  if (teachingSubject === 'IT' || teachingSubject === 'Information Technology') {
    teachingSubject = 'ICT';
  }

  // 🟢 ඩේටාබේස් (phpMyAdmin) එකෙන් ලයිව්ම දත්ත ලබාගන්නා ප්‍රධාන Function එක
  const refreshData = () => {
    axiosInstance.get('http://localhost:8081/api/quizzes')
      .then(res => {
        const allQuizzes = Array.isArray(res.data) ? res.data : [];
        setQuizzes(allQuizzes.filter(q => q.subject_name === teachingSubject));
      })
      .catch(err => console.log("Quizzes Fetch Error:", err));
    
    axiosInstance.get('http://localhost:8081/api/question-bank')
      .then(res => {
        setMasterBank(Array.isArray(res.data) ? res.data : []);
      })
      .catch(err => console.log("Question Bank Fetch Error:", err));
  };

  useEffect(() => { 
    refreshData(); 
  }, [teachingSubject]);

  // 1. New Paper Title සාදා ඩේටාබේස් එකට යැවීම
  const handleCreatePaper = (e) => {
    e.preventDefault();
    const payload = { title: quizTitle, grade: teachingGrade, subject: teachingSubject, teacher_name: userName };
    
    axiosInstance.post('http://localhost:8081/api/add-quiz', payload)
      .then(res => {
        if (res.data.status === "Success") {
          alert(`✅ Quiz Paper "${quizTitle}" Created Successfully!`);
          setQuizTitle('');
          refreshData();
        }
      })
      .catch(err => alert("Error creating paper: " + err.message));
  };

  // 2. අලුත්ම ප්‍රශ්නයක් ලියා කෙලින්ම ඩේටාබේස් බැංකුවට සේව් කිරීම
  const handleSaveQuestion = (e) => {
    e.preventDefault();
    const payload = {
      quiz_id: selectedQuizId ? parseInt(selectedQuizId) : 0, // පේපර් එකක් තෝරා ඇත්නම් ඒකට ලින්ක් වේ, නැතහොත් බැංකුවට පමණක් වැටේ
      question_text: qText, 
      marks: qMarks,
      option_a: optA, 
      option_b: optB, 
      option_c: optC, 
      option_d: optD, 
      correct_option: correctOpt
    };

    if (editingId) {
      axiosInstance.put(`http://localhost:8081/api/edit-question/${editingId}`, payload)
        .then(res => {
          if (res.data.status === "Success") {
            alert("✅ Question Content Updated in Database!");
            setEditingId(null); 
            clearForm(); 
            refreshData();
          }
        })
        .catch(err => alert("Error updating question: " + err.message));
    } else {
      axiosInstance.post('http://localhost:8081/api/add-question', payload)
        .then(res => {
          if (res.data.status === "Success") {
            alert("✅ ප්‍රශ්නය සාර්ථකව ඩේටාබේස් ප්‍රශ්න බැංකුවට එකතු කරන ලදි!");
            clearForm(); 
            refreshData();
          }
        })
        .catch(err => alert("Error saving question: " + err.message));
    }
  };

  // 🟢 3. බැංකුවේ ඇති ප්‍රශ්නයක් එක ක්ලික් එකෙන් ඩේටාබේස් එක හරහා පේපර් එකට ලින්ක් කිරීම
  const handleQuickLink = (question) => {
    if (!selectedQuizId) { 
      alert("⚠️ කරුණාකර මුලින්ම Step 2 එකෙන් පේපර් එකක් තෝරන්න!"); 
      return; 
    }
    
    const payload = {
      quiz_id: parseInt(selectedQuizId),
      question_text: question.question_text,
      marks: question.marks,
      option_a: question.option_a,
      option_b: question.option_b,
      option_c: question.option_c,
      option_d: question.option_d,
      correct_option: question.correct_option
    };

    axiosInstance.put(`http://localhost:8081/api/edit-question/${question.id}`, payload)
      .then(res => {
        if (res.data.status === "Success") {
          alert("➕ ප්‍රශ්නය සාර්ථකව විභාග ප්‍රශ්න පත්‍රයට ලින්ක් කරන ලදි!");
          refreshData();
        }
      })
      .catch(err => alert("Error linking question: " + err.message));
  };

  // 4. ප්‍රශ්නයක් ඩේටාබේස් එකෙන් සහමුලින්ම මකා දැමීම
  const handleDeleteQuestion = (id) => {
    if (window.confirm("Are you sure you want to delete this question permanently from Database?")) {
      axiosInstance.delete(`http://localhost:8081/api/delete-question/${id}`)
        .then(res => {
          if (res.data.status === "Success") {
            alert("🗑️ Question removed from Database!");
            refreshData();
          }
        })
        .catch(err => alert("Error deleting question: " + err.message));
    }
  };

  // 5. පේපර් එකෙන් අයින් කර නැවත බැංකුවටම දැමීම (Unlink)
  const handleUnlinkQuestion = (question) => {
    const payload = {
      quiz_id: 0, // 0 කළ විට පේපර් එකෙන් ඉවත් වේ
      question_text: question.question_text,
      marks: question.marks,
      option_a: question.option_a,
      option_b: question.option_b,
      option_c: question.option_c,
      option_d: question.option_d,
      correct_option: question.correct_option
    };

    axiosInstance.put(`http://localhost:8081/api/edit-question/${question.id}`, payload)
      .then(res => {
        if (res.data.status === "Success") {
          refreshData();
        }
      });
  };

  const clearForm = () => {
    setQText(''); setOptA(''); setOptB(''); setOptC(''); setOptD(''); setCorrectOpt('A');
  };

  const handleStartEdit = (q) => {
    setEditingId(q.id); setQText(q.question_text);
    setOptA(q.option_a); setOptB(q.option_b); setOptC(q.option_c); setOptD(q.option_d);
    setCorrectOpt(q.correct_option); setQMarks(q.marks);
  };

  // දැනට තෝරාගත් පේපර් ID එකට අදාළ ප්‍රශ්න පමණක් වෙන් කර ගැනීම
  const activePaperQuestions = masterBank.filter(q => q.quiz_id === parseInt(selectedQuizId));

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '25px' }}>
      
      {/* HEADER */}
      <div>
        <h2 style={{ color: '#1e293b', margin: 0 }}>📝 Mathematics MCQ Exam & Paper Manager</h2>
        <p style={{ color: '#64748b', fontSize: '14px', marginTop: '5px' }}>
          ප්‍රශ්න බැංකුවෙන් තෝරාගෙන විභාග ප්‍රශ්න පත්‍ර (MCQ Tute Builder) සකස් කිරීමේ මධ්‍යස්ථානය.
        </p>
      </div>

      {/* STEP 1 & 2 TOP CONTROL GRID */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
        <div style={styles.card('#15803d')}>
          <h4 style={styles.stepTitle('#15803d')}>Step 1: Create a New Quiz Paper Title</h4>
          <form onSubmit={handleCreatePaper} style={{ display: 'flex', gap: '10px' }}>
            <input type="text" placeholder="e.g., 2 වාර මැද ඇගයීම" value={quizTitle} onChange={e => setQuizTitle(e.target.value)} required style={styles.fullInput} />
            <button type="submit" style={{ ...styles.btn, backgroundColor: '#15803d' }}>Create</button>
          </form>
        </div>

        <div style={styles.card('#2563eb')}>
          <h4 style={styles.stepTitle('#2563eb')}>Step 2: Active Exam Paper Target</h4>
          <select value={selectedQuizId} onChange={e => setSelectedQuizId(e.target.value)} style={styles.fullInput}>
            <option value="">-- Choose Target Exam Paper --</option>
            {quizzes.map(q => (
              <option key={q.id} value={q.id}>{q.title} ({q.grade})</option>
            ))}
          </select>
        </div>
      </div>

      {/* MAIN LAYOUT */}
      <div style={{ display: 'grid', gridTemplateColumns: '1.1fr 1.3fr', gap: '25px', alignItems: 'start' }}>
        
        {/* LEFT: FORM */}
        <div style={styles.card('#475569')}>
          <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b' }}>➕ Add Custom Question to Bank</h3>
          <form onSubmit={handleSaveQuestion} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <div>
              <label style={styles.label}>ප්‍රශ්න විස්තරය</label>
              <textarea placeholder="ගණිත ගැටලුව මෙතන ලියන්න..." value={qText} onChange={e => setQText(e.target.value)} required style={{ ...styles.fullInput, height: '60px', resize: 'none' }} />
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'A'} onChange={() => setCorrectOpt('A')} name="ans" /><input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'B'} onChange={() => setCorrectOpt('B')} name="ans" /><input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'C'} onChange={() => setCorrectOpt('C')} name="ans" /><input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} required style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'D'} onChange={() => setCorrectOpt('D')} name="ans" /><input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} required style={styles.fullInput} /></div>
            </div>
            <button type="submit" style={{ ...styles.btn, backgroundColor: '#475569', padding: '11px' }}>
              Save Inside Repository Bank 💾
            </button>
          </form>
        </div>

        {/* RIGHT: THE QUESTION BANK REPOSITORY */}
        <div style={styles.card('#6b21a8')}>
          <h3 style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#1e293b' }}>📚 Central Question Bank Repository</h3>
          <p style={{ margin: '0 0 15px 0', fontSize: '12px', color: '#64748b' }}>ඩේටාබේස් එකෙන් ලෝඩ් වන ප්‍රශ්න. ඒවා පේපර් එකට ඇතුළත් කිරීමට කොළ පාට බටන් එක ඔබන්න.</p>
          
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '350px', overflowY: 'auto', paddingRight: '5px' }}>
            {masterBank.length > 0 ? (
              masterBank.map((q, idx) => {
                const isLinked = q.quiz_id > 0;
                
                return (
                  <div key={q.id || idx} style={{ backgroundColor: '#f8fafc', padding: '15px', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '11px', marginBottom: '6px' }}>
                      <span style={{ color: '#64748b', fontWeight: 'bold' }}>Question Ref #{idx + 1}</span>
                      <span style={{ color: window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId) ? '#16a34a' : isLinked ? '#2563eb' : '#ea580c', fontWeight: 'bold' }}>
                        {window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId) ? '✓ Added to Current Paper' : isLinked ? 'Linked to Other Paper' : '📌 Available in Bank'}
                      </span>
                    </div>
                    <h5 style={{ margin: '0 0 10px 0', fontSize: '13.5px', color: '#1e293b', lineHeight: '1.4' }}>{q.question_text}</h5>
                    <div style={{ display: 'flex', gap: '10px' }}>
                      <button onClick={() => handleStartEdit(q)} style={styles.miniBtn}>✏️ Edit</button>
                      <button onClick={() => handleDeleteQuestion(q.id)} style={{ ...styles.miniBtn, color: '#b91c1c', backgroundColor: '#fee2e2' }}>🗑️ Delete</button>
                      
                      <button 
                        onClick={() => handleQuickLink(q)} 
                        disabled={window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId)}
                        style={{ 
                          ...styles.miniBtn, 
                          backgroundColor: window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId) ? '#cbd5e1' : '#16a34a', 
                          color: 'white', 
                          border: 'none',
                          marginLeft: 'auto'
                        }}
                      >
                        {window.parseInt(q.quiz_id) === window.parseInt(selectedQuizId) ? 'Added ✓' : '➕ Link to Active Paper'}
                      </button>
                    </div>
                  </div>
                );
              })
            ) : (
              <p style={{ color: '#94a3b8', textAlign: 'center', fontSize: '13px', fontStyle: 'italic', padding: '20px' }}>
                📭 ප්‍රශ්න බැංකුව හිස්ව පවතී. phpMyAdmin මගින් ඩේටා ඇතුළත් කරන්න හෝ වම් පසින් එකතු කරන්න.
              </p>
            )}
          </div>
        </div>

      </div>

      {/* BOTTOM DISPLAY: EXAM PREVIEW SHEET */}
      <div style={{ marginTop: '5px' }}>
        <h3 style={{ color: '#1e293b', marginBottom: '12px' }}>📝 Live Math MCQ Examination Paper Layout Preview</h3>
        <div style={{ backgroundColor: 'white', padding: '40px', borderRadius: '16px', border: '1px solid #cbd5e1', boxShadow: '0 4px 20px rgba(0,0,0,0.01)' }}>
          
          <div style={{ borderBottom: '3px double #334155', paddingBottom: '15px', marginBottom: '30px', textAlign: 'center' }}>
            <span style={{ fontSize: '12px', fontWeight: 'bold', color: '#2563eb', letterSpacing: '1.5px', backgroundColor: '#dbeafe', padding: '3px 12px', borderRadius: '10px' }}>
              AURA EDUCATION SYSTEM - OFFICIAL ASSESSMENT SHEET
            </span>
            <h3 style={{ margin: '10px 0 5px 0', fontSize: '20px', color: '#1e293b' }}>
              {selectedQuizId && quizzes.find(qz => qz.id === parseInt(selectedQuizId)) ? quizzes.find(qz => qz.id === parseInt(selectedQuizId)).title : "Active Examination"}
            </h3>
            <div style={{ display: 'flex', justifyContent: 'center', gap: '20px', fontSize: '13px', color: '#64748b', fontWeight: '500', marginTop: '5px' }}>
              <span>Subject: Mathematics</span>
              <span>Target Structure: {teachingGrade}</span>
              <span>Total Questions: {activePaperQuestions.length}</span>
            </div>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>
            {activePaperQuestions.length > 0 ? (
              activePaperQuestions.map((q, idx) => (
                <div key={q.id || idx} style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                  
                  <div style={{ display: 'flex', gap: '10px', fontSize: '15px', fontWeight: '600', color: '#1e293b' }}>
                    <span>({idx + 1})</span>
                    <p style={{ margin: 0, flex: 1, lineHeight: '1.4' }}>{q.question_text}</p>
                    <button onClick={() => handleUnlinkQuestion(q)} style={{ border: 'none', background: 'none', color: '#ef4444', fontSize: '11px', cursor: 'pointer', fontWeight: 'bold' }}>[❌ Remove Paper]</button>
                  </div>

                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', paddingLeft: '30px', marginTop: '4px' }}>
                    <div style={styles.previewOpt}><input type="radio" disabled checked={q.correct_option === 'A'} /> <span>(A) {q.option_a}</span></div>
                    <div style={styles.previewOpt}><input type="radio" disabled checked={q.correct_option === 'B'} /> <span>(B) {q.option_b}</span></div>
                    <div style={styles.previewOpt}><input type="radio" disabled checked={q.correct_option === 'C'} /> <span>(C) {q.option_c}</span></div>
                    <div style={styles.previewOpt}><input type="radio" disabled checked={q.correct_option === 'D'} /> <span>(D) {q.option_d}</span></div>
                  </div>

                  <div style={{ paddingLeft: '30px', fontSize: '12px', color: '#16a34a', fontWeight: 'bold', marginTop: '4px' }}>
                    🔑 Correct System Answer Matrix Key: Option ({q.correct_option})
                  </div>

                </div>
              ))
            ) : (
              <div style={{ textAlign: 'center', padding: '40px', color: '#94a3b8', fontStyle: 'italic' }}>
                📭 මෙම ප්‍රශ්න පත්‍රය දැනට හිස්ව පවතී. දකුණු පස ඇති ප්‍රශ්න බැංකුවේ ඇති ප්‍රශ්න ළඟ ඇති "➕ Link to Active Paper" බටන් එක ඔබා පේපර් එක සාදා පෙන්වන්න.
              </div>
            )}
          </div>

          <div style={{ marginTop: '40px', paddingTop: '15px', borderTop: '1px dashed #cbd5e1', fontSize: '12px', color: '#94a3b8', textAlign: 'center' }}>
            © Aura Pen Saku Central Examination Portal. All structures synchronized.
          </div>

        </div>
      </div>

    </div>
  );
}

const styles = {
  card: (color) => ({ backgroundColor: 'white', padding: '24px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.02)', borderTop: `5px solid ${color}`, display: 'flex', flexDirection: 'column' }),
  stepTitle: (color) => ({ margin: '0 0 12px 0', fontSize: '14.5px', color: color, fontWeight: 'bold' }),
  fullInput: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', fontSize: '13.5px', boxSizing: 'border-box' },
  btn: { color: 'white', border: 'none', padding: '11px 20px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13.5px' },
  label: { display: 'block', fontSize: '12px', fontWeight: 'bold', color: '#475569', marginBottom: '6px' },
  optRow: { display: 'flex', alignItems: 'center', gap: '10px', width: '100%' },
  miniBtn: { padding: '6px 12px', border: '1px solid #cbd5e1', backgroundColor: 'white', borderRadius: '6px', cursor: 'pointer', fontSize: '11.5px', fontWeight: 'bold', color: '#334155' },
  previewOpt: { display: 'flex', alignItems: 'center', gap: '8px', fontSize: '14px', color: '#334155', fontWeight: '500' }
};
